# Install-CommitClone.ps1 — one-shot installer for Commit-Clone v2
# Usage: right-click this file → "Run with PowerShell"
#   OR:  in PowerShell, cd to the folder, then:  .\Install-CommitClone.ps1

$ErrorActionPreference = 'Stop'

Write-Host ""
Write-Host "Installing Commit-Clone v2 helpers..." -ForegroundColor Cyan
Write-Host ""

# 1. Ensure profile exists
if (-not (Test-Path $PROFILE)) {
    New-Item -ItemType File -Path $PROFILE -Force | Out-Null
    Write-Host "  Created profile at: $PROFILE" -ForegroundColor DarkGray
} else {
    Write-Host "  Profile: $PROFILE" -ForegroundColor DarkGray
}

# 2. Back up existing profile if it has old v1 code
$cur = Get-Content $PROFILE -Raw -ErrorAction SilentlyContinue
if ($cur -and $cur -match 'Commit-CloneFromClipboard') {
    $backup = "$PROFILE.bak-$(Get-Date -f yyyyMMddHHmmss)"
    Copy-Item $PROFILE $backup
    Write-Host "  Found old v1 code. Backed up to: $backup" -ForegroundColor Yellow
    Write-Host "  (Old code stays in the file below the new code, but v2 will win on load.)" -ForegroundColor DarkGray
}

# 3. Decode and append v2
$b64 = @'

'@
$b64 = $b64 -replace '\s',''
$script = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($b64))
Add-Content -Path $PROFILE -Value "`n# ---- Commit-Clone v2 (installed $(Get-Date -f yyyy-MM-dd)) ----`n$script" -Encoding utf8
Write-Host "  Appended v2 script to profile." -ForegroundColor Green

# 4. Reload
. $PROFILE

# 5. Verify
Write-Host ""
Write-Host "Verifying with a dry run (empty clipboard expected to error out cleanly):" -ForegroundColor Cyan
Write-Host ""
try {
    if (Get-Command Commit-CloneFromClipboard -ErrorAction SilentlyContinue) {
        Write-Host "  Function loaded ✓" -ForegroundColor Green
        Write-Host ""
        Write-Host "Ready. Next time you have a draft copied, run:" -ForegroundColor White
        Write-Host "  Commit-CloneFromClipboard" -ForegroundColor Yellow
    } else {
        Write-Host "  Function NOT loaded ✗" -ForegroundColor Red
        Write-Host "  Try closing and reopening PowerShell." -ForegroundColor Yellow
    }
} catch {
    Write-Host "  Error during verify: $_" -ForegroundColor Red
}

Write-Host ""
Read-Host "Press Enter to close"
